ALTER TABLE memory_alias_bindings ADD CONSTRAINT memory_alias_bindings_payload_object CHECK ((jsonb_typeof(payload) = 'object'::text));
ALTER TABLE memory_authorization_receipts ADD CONSTRAINT memory_authorization_receipts_payload_object CHECK ((jsonb_typeof(payload) = 'object'::text));
ALTER TABLE memory_identity_edges ADD CONSTRAINT memory_identity_edges_payload_object CHECK ((jsonb_typeof(payload) = 'object'::text));
ALTER TABLE memory_key_destruction_obligations ADD CONSTRAINT memory_key_destruction_obligations_reason_domain CHECK ((not_proven_reason = ANY (ARRAY['NO_PROVIDER_CONFIGURED'::text, 'PROVIDER_UNAVAILABLE'::text, 'PROVIDER_TIMEOUT'::text, 'PROVIDER_DOES_NOT_OWN_KEY'::text, 'PROVIDER_ANSWERED_UNKNOWN'::text, 'CONTRADICTORY_EVIDENCE'::text, 'SETTLED'::text])));
ALTER TABLE memory_key_destruction_obligations ADD CONSTRAINT memory_key_destruction_obligations_resolution_named CHECK ((((state = 'KEY_DESTRUCTION_NOT_PROVEN'::text) AND (resolved_by IS NULL) AND (settled_by IS NULL)) OR ((state <> 'KEY_DESTRUCTION_NOT_PROVEN'::text) AND (resolved_by = ANY (ARRAY['PROVIDER'::text, 'SETTLEMENT'::text])) AND ((resolved_by = 'SETTLEMENT'::text) = (settled_by IS NOT NULL)))));
ALTER TABLE memory_key_destruction_obligations ADD CONSTRAINT memory_key_destruction_obligations_state_domain CHECK ((state = ANY (ARRAY['KEY_DESTRUCTION_NOT_PROVEN'::text, 'PROVEN_DESTROYED'::text, 'PROVEN_NOT_DESTROYED'::text])));
ALTER TABLE memory_key_destruction_settlements ADD CONSTRAINT memory_key_destruction_settlements_decision_domain CHECK ((decision = ANY (ARRAY['PROVEN_DESTROYED'::text, 'PROVEN_NOT_DESTROYED'::text, 'STILL_UNKNOWN'::text, 'RETENTION_BLOCKED'::text, 'PROVIDER_UNAVAILABLE'::text, 'EVIDENCE_INSUFFICIENT'::text, 'CONTRADICTORY_EVIDENCE'::text])));
ALTER TABLE memory_key_destruction_settlements ADD CONSTRAINT memory_key_destruction_settlements_digest_shape CHECK ((evidence_digest ~ '^sha256:[0-9a-f]{64}$'::text));
ALTER TABLE memory_key_destruction_settlements ADD CONSTRAINT memory_key_destruction_settlements_policy_known CHECK ((policy_version = 'aaliyah.key-destruction-settlement/v1'::text));
ALTER TABLE memory_key_destruction_settlements ADD CONSTRAINT memory_key_destruction_settlements_states_known CHECK (((predecessor_state = ANY (ARRAY['ERASURE_REQUESTED'::text, 'ERASURE_PENDING_SETTLEMENT'::text, 'PROVEN_DESTROYED'::text, 'PROVEN_NOT_DESTROYED'::text])) AND (successor_state = ANY (ARRAY['ERASURE_REQUESTED'::text, 'ERASURE_PENDING_SETTLEMENT'::text, 'PROVEN_DESTROYED'::text, 'PROVEN_NOT_DESTROYED'::text]))));
ALTER TABLE memory_legal_holds ADD CONSTRAINT memory_legal_holds_payload_object CHECK ((jsonb_typeof(payload) = 'object'::text));
ALTER TABLE memory_mutation_attempts ADD CONSTRAINT memory_mutation_attempts_payload_object CHECK ((jsonb_typeof(payload) = 'object'::text));
ALTER TABLE memory_mutation_receipts ADD CONSTRAINT memory_mutation_receipts_payload_object CHECK ((jsonb_typeof(payload) = 'object'::text));
ALTER TABLE memory_pii_key_audits ADD CONSTRAINT memory_pii_key_audits_state_domain CHECK ((last_state = ANY (ARRAY['active'::text, 'destroyed'::text, 'unknown'::text, 'unreachable'::text])));
ALTER TABLE memory_reconciliations ADD CONSTRAINT memory_reconciliations_evidence_object CHECK ((jsonb_typeof(evidence) = 'object'::text));
ALTER TABLE memory_record_versions ADD CONSTRAINT memory_record_versions_payload_object CHECK ((jsonb_typeof(payload) = 'object'::text));
ALTER TABLE memory_tombstones ADD CONSTRAINT memory_tombstones_payload_object CHECK ((jsonb_typeof(payload) = 'object'::text));
